import Foundation
final class ExportStore {
    private let lock = NSLock()
    private var text = "Черновик"
    func export(build: (String) -> String) -> String {
        lock.lock()
        let snapshot = text
        lock.unlock()
        return build(snapshot)
    }
    func read() -> String {
        lock.lock(); defer { lock.unlock() }
        return text
    }
}

Расчёт получает «Черновик» после unlock. build может безопасно вызвать read; длительная работа больше не удерживает этот lock.

func plan(interactive: [Int], background: [Int]) -> [Int] {
    var result: [Int] = []
    let count = max(interactive.count, background.count)
    for index in 0..<count {
        if index < interactive.count { result.append(interactive[index]) }
        if index < background.count { result.append(background[index]) }
    }
    return result
}
print(plan(interactive: [31, 32, 33], background: [40, 41]))

Вывод [31, 40, 32, 41, 33]. Обе непустые очереди получают слоты.

